INSERT INTO blog_post_translations
  (post_id, locale, slug, title, excerpt, body_html, seo_title, seo_description)
VALUES (
  :post_id, 'uz', $x$telegram-stars-sotib-olish$x$,
  $x$Telegram Stars: bu nima va Oʻzbekistonda qanday sotib olinadi$x$,
  $x$Telegram Stars nima, ularni nimaga sarflash mumkin va Oʻzbekistonda soʻmda qanday sotib olish: username orqali, parolsiz va xorijiy kartasiz.$x$,
$x$<h2>Asosiysi</h2>
<ul>
<li>Telegram Stars — Telegram’ning ichki valyutasi. Ular bilan botlar va mini-ilovalarga, pullik postlar, kanal obunalari va sovgʻalar uchun toʻlanadi.</li>
<li>Stars — bir martalik xaridlar uchun. Telegram Premium — messenjerning oʻz funksiyalariga obuna.</li>
<li>Ilova ichida yulduzlar App Store, Google Play yoki @PremiumBot orqali, doʻkon valyutasida sotiladi.</li>
<li>YuPay’da yulduzlar @username orqali, 50 dan 15 000 tagacha olinadi, toʻlov Click, Payme yoki Uzum orqali soʻmda.</li>
</ul>
<p>Telegram Stars’ni Oʻzbekistonda xorijiy kartasiz sotib olish mumkin: soʻmda toʻlaysiz, yulduzlar esa username orqali akkauntingizga tushadi. Quyida bu valyuta nima, uni nimaga sarflash va qanday sotib olish haqida.</p>
<h2>Telegram Stars nima</h2>
<p>Telegram Stars — Telegram akkauntingiz ichidagi balans. Telegram yulduzlarni 2024-yil 6-iyunda messenjer ichida raqamli tovarlar uchun yagona toʻlov usuli sifatida ishga tushirgan (<a href="https://telegram.org/blog/telegram-stars">Telegram blogi</a>).</p>
<p>Yulduzlar qurilmaga emas, akkauntga bogʻlangan. Telefonni almashtirdingiz yoki kompyuterdan kirdingiz — balans oʻsha-oʻsha.</p>
<p>Yulduzlar qayerda sarflanadi:</p>
<ul>
<li>botlar va mini-ilovalardagi xaridlar: xizmat funksiyalari, mini-oʻyinlardagi buyumlar;</li>
<li>kanallardagi pullik postlar: yopiq foto va videolar;</li>
<li>yopiq kanallarga obunalar;</li>
<li>mualliflarni qoʻllab-quvvatlash uchun yulduzli reaksiyalar;</li>
<li>boshqa foydalanuvchilarga sovgʻalar, jumladan Telegram Premium.</li>
</ul>
<p>Bitta cheklov: oddiy foydalanuvchi yulduzlarni qaytarib pulga aylantira olmaydi. Qancha sarflamoqchi boʻlsangiz, shuncha oling.</p>
<h2>Yulduzlarni nimaga sarflash mumkin</h2>
<p><strong>Sovgʻalar.</strong> Sovgʻani tanlaysiz, yulduz bilan toʻlaysiz va chatga yuborasiz. Sovgʻa oluvchining profilida qoladi.</p>
<p><strong>Pullik kontent.</strong> Muallif postni yopadi yoki kanalga yulduz evaziga obuna orqali kirish beradi. Taʼlim kanallari va mualliflik hamjamiyatlari shunday pul oladi.</p>
<p><strong>Botlar va mini-ilovalar.</strong> Yulduzlarga xizmatlarning kengaytirilgan funksiyalari va mini-oʻyinlardagi buyumlar olinadi. Oʻyin valyutasi kabi ishlaydi, faqat Telegram’ning oʻzida.</p>
<p><strong>Yulduzli reaksiyalar.</strong> Post ostida muallifga kichik summa, alohida oʻtkazmasiz.</p>
<h2>YuPay’da Telegram Stars’ni soʻmda qanday sotib olish</h2>
<p>Telegram ichida yulduzlar App Store, Google Play yoki @PremiumBot orqali olinadi. Narx doʻkon valyutasida, doʻkon qabul qiladigan karta kerak. Oʻzbekistonda koʻpchilikda bunday karta yoʻq.</p>
<p>YuPay’da toʻlov soʻmda:</p>
<ol>
<li><a href="/uz/store/telegram-stars">Telegram Stars sahifasini</a> oching.</li>
<li>Telegram’dagi @username’ingizni kiriting (Sozlamalar → Foydalanuvchi nomi).</li>
<li>Miqdorni tanlang: 50 dan 15 000 tagacha yulduz.</li>
<li>Click, Payme yoki Uzum orqali toʻlang.</li>
</ol>
<p>Yulduzlar akkauntga avtomatik tushadi. Soʻmdagi yakuniy summa toʻlovdan oldin koʻrinadi va aynan shu summa yechiladi.</p>
<p>Parol ham, kirish kodi ham kerak emas — faqat ochiq foydalanuvchi nomi. Toʻlovdan oldin username’ni tekshiring: yulduzlar siz koʻrsatgan akkauntga tushadi.</p>
<h2>Stars yoki Premium</h2>
<p>Bu ikki xil mahsulot.</p>
<p><strong>Stars</strong> — aniq xaridlar uchun: sovgʻa, post, mini-oʻyindagi buyum, bot funksiyasi. Olganingiz uchun toʻlaysiz, balans kuyib ketmaydi.</p>
<p><strong>Premium</strong> — 3, 6 yoki 12 oylik obuna. Reklamani olib tashlaydi, yuklash limitlarini oshiradi va interfeys funksiyalarini qoʻshadi. Batafsil — <a href="/uz/blog/telegram-premium">Oʻzbekistonda Telegram Premium</a> maqolasida.</p>
<p>Ikkalasini ham sovgʻa qilish mumkin. Yulduzlarni oluvchi oʻzi sarflaydi, Premium esa muddatli tayyor obuna.</p>
<h2>Yulduzlar koʻrinmasa</h2>
<p>Telegram’da Sozlamalar → Mening yulduzlarim boʻlimini oching: balans oʻsha yerda. Yulduzlar boʻlmasa, buyurtmadagi username’ni tekshiring. U toʻgʻri boʻlsa, YuPay qoʻllab-quvvatlash xizmatiga yozing — buyurtma raqami xatda bor.</p>
<h2>Nimadan boshlash kerak</h2>
<p>Xaridingiz uchun qancha yulduz kerakligini aniqlang. <a href="/uz/store/telegram-stars">YuPay’dagi Telegram Stars</a> sahifasini oching, @username’ni kiriting va soʻmda toʻlang.</p>$x$,
  $x$Telegram Stars: Oʻzbekistonda soʻmda sotib olish$x$,
  $x$Telegram Stars nima va ular nimaga sarflanadi. Oʻzbekistonda yulduzlarni username orqali sotib olish: Click, Payme yoki Uzum orqali soʻmda, xorijiy kartasiz.$x$
);

